  FUNCTION ONUMM3N20_MATMUL_ONUMM3N20(LHS,RHS)&
    RESULT(RES)
    IMPLICIT NONE
    TYPE(ONUMM3N20), INTENT(IN) :: LHS(:,:) 
    TYPE(ONUMM3N20), INTENT(IN) :: RHS(:,:) 
    TYPE(ONUMM3N20) :: TMP 
    TYPE(ONUMM3N20) :: RES(SIZE(LHS,1),SIZE(RHS,2)) 
    INTEGER :: I,J,K 

    ! Dimension check
    IF (SIZE(LHS,2) /= SIZE(RHS,1)) THEN
      STOP "Runtime error: " // &
           "Dimension mismatch in MATMUL."
    END IF
    DO I = 1, SIZE(LHS,1)
      DO J = 1, SIZE(RHS,2)
        TMP = 0.0_DP
        DO K = 1, SIZE(LHS,2)
          TMP = TMP + LHS( I, K )*RHS( K, J )
        END DO
        RES( I, J ) = TMP
      END DO
    END DO

  END FUNCTION ONUMM3N20_MATMUL_ONUMM3N20

